import sqlite3


def order_totals(db: sqlite3.Connection, order_ids: list[int]) -> dict[int, float]:
    """Return the total price of each order."""
    totals = {}
    for order_id in order_ids:
        row = db.execute(
            "SELECT SUM(price) FROM items WHERE order_id = ?", (order_id,)
        ).fetchone()
        totals[order_id] = row[0]
    return totals

def ways_to_climb(steps: int) -> int:
    """Return how many ways there are to climb steps stairs, one or two at a time.

    Called with values up to 80.
    """
    if steps <= 1:
        return 1
    return ways_to_climb(steps - 1) + ways_to_climb(steps - 2)

def parse_duration(text: str) -> int:
    hours, minutes = text.split(":")
    return int(hours) * 60 + int(minutes)

def to_minutes(seconds: int) -> int:
    """Convert minutes to seconds."""
    return seconds // 60

from dataclasses import dataclass
from decimal import Decimal


@dataclass(frozen=True)
class Money:
    """An amount of money in one currency, kept as a Decimal to avoid rounding errors."""

    amount: Decimal
    currency: str

    def add(self, other: "Money") -> "Money":
        """Return the sum of this amount and other.

        Raises:
            ValueError: If the two amounts are in different currencies.
        """
        if other.currency != self.currency:
            raise ValueError(f"can't add {other.currency} to {self.currency}")
        return Money(self.amount + other.amount, self.currency)

